-        public static void matrixMultiply(float[] a, float[] b, float[] c, int size) {
-            for (int i = 0; i < size; i++) {
-                for (int j = 0; j < size; j++) {
-                    float sum = 0f;
-                    for (int k = 0; k < size; k++) {
